"""Same binary across two sweeps (noise floor), and aligned against unaligned levels."""
import json, sys
def load(p):
    d = {}
    for l in open(p):
        r = json.loads(l); d.setdefault((r["bench"], r["tags"]["build"]), []).append(r["mean_ns"])
    return d
tm = lambda v: sum(sorted(v)[1:5]) / 4
a, b = load(sys.argv[1]), load(sys.argv[2])
same, cost = [], []
for (bench, build), v in a.items():
    if build in ("bold5-cgu1", "bnow5-cgu1") and (bench, build) in b:
        same.append(abs(100 * (tm(b[(bench, build)]) - tm(v)) / tm(v)))
for (bench, build), v in b.items():
    if build == "bold5-al":
        c = tm(b[(bench, "bold5-cgu1")])
        cost.append((100 * (tm(v) - c) / c, bench))
same.sort(); cost.sort()
print(f"same binary, two sweeps: median |d| {same[len(same)//2]:.2f}%, over 2%: {sum(x>2 for x in same)} of {len(same)}, max {same[-1]:.1f}%")
print("aligned against cgu1 (old tree): median %+.2f%%, range %+.1f%% (%s) to %+.1f%% (%s)" % (cost[len(cost)//2][0], cost[0][0], cost[0][1], cost[-1][0], cost[-1][1]))
EOF
